{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "Tobramycin, a closely related aminoglycoside, showed very low or unmeasurable CSF concentrations in neonates, demonstrating that aminoglycosides do not achieve meaningful CNS exposure after systemic dosing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Whole-body autoradiography after i.v. administration of F-TAC, an aminoglycoside, showed rapid distribution to all tissues except brain and nervous tissues, directly supporting poor CNS access for this chemical class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Kanamycin was detected in CSF in animals at concentrations related to blood, providing limited contradictory evidence that some aminoglycosides can enter CSF; this does not establish meaningful brain exposure and may reflect specific experimental conditions.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Streptomycin is a highly polar, polycationic aminoglycoside with physicochemical properties incompatible with passive BBB diffusion. Direct aminoglycoside evidence (tobramycin, F-TAC) shows poor CNS penetration, and the limited kanamycin CSF detection is context-dependent. Therefore, systemic administration is unlikely to provide meaningful CNS access.",
  "evidence_gaps": [
    "No direct streptomycin brain or CSF pharmacokinetic measurement is present in the provided evidence set.",
    "Most aminoglycoside CSF data come from neonates or inflamed-meninges contexts, which may overestimate penetration.",
    "Transporter-mediated uptake or efflux for streptomycin was not directly assessed."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

